void generateMonthlyReport(const std::vector<Claim>& claims, const std::vector<Provider>& providers) -> std::json {
  std::map<ClaimStatus, int> claimCounts;
  std::map<ClaimStatus, std::vector<Provider>> claimProviders;

  for (const auto& claim : claims) {
    claimCounts[claim.getStatus()]++;
    claimProviders[claim.getStatus()].push_back(claim.getProvider());
  }

  std::json report;
  report["paidWithoutReservation"] = claimCounts[ClaimStatus::PaidWithoutReservation];
  report["paymentWithHeld"] = claimCounts[ClaimStatus::PaymentWithHeld];

  return report;
}

void generateClaimsPerProviderReport(const std::vector<Claim>& claims, const std::vector<Provider>& providers) -> std::json {
